package pool

import (
	"context"
	"sync"
)

type Task func(ctx context.Context)

type WorkerPool struct {
	workers int
	tasks   chan Task
	wg      sync.WaitGroup
	ctx     context.Context
	cancel  context.CancelFunc
}

func NewWorkerPool(ctx context.Context, workers, queueCap int) *WorkerPool {
	c, cancel := context.WithCancel(ctx)
	p := &WorkerPool{
		workers: workers,
		tasks:   make(chan Task, queueCap),
		ctx:     c,
		cancel:  cancel,
	}
	for i := 0; i < workers; i++ {
		p.wg.Add(1)
		go p.worker()
	}
	return p
}

func (p *WorkerPool) worker() {
	defer p.wg.Done()
	for {
		select {
		case <-p.ctx.Done():
			return
		case task, ok := <-p.tasks:
			if !ok {
				return
			}
			task(p.ctx)
		}
	}
}

func (p *WorkerPool) Submit(task Task) bool {
	select {
	case <-p.ctx.Done():
		return false
	case p.tasks <- task:
		return true
	}
}

func (p *WorkerPool) Close() {
	p.cancel()
	close(p.tasks)
	p.wg.Wait()
}

